import csv
import sys

def net_cents(total_cents, discount_percent):
    if type(total_cents) is not int or total_cents < 0:
        raise ValueError("total_cents must be a nonnegative integer")
    if type(discount_percent) is not int or not 0 <= discount_percent <= 100:
        raise ValueError("discount_percent must be an integer from 0 to 100")
    return total_cents * discount_percent // 100

def export(source, target):
    with open(source, newline="", encoding="utf-8") as src, open(target, "w", newline="", encoding="utf-8") as dst:
        rows = csv.DictReader(src)
        out = csv.DictWriter(dst, fieldnames=["id", "net_cents"])
        out.writeheader()
        for row in rows:
            out.writerow({"id": row["id"], "net_cents": net_cents(int(row["total_cents"]), int(row["discount_percent"]))})

if __name__ == "__main__":
    export(*sys.argv[1:])

