import unittest
from billing import net_cents

class BillingTest(unittest.TestCase):
    def test_discount(self):
        self.assertEqual(net_cents(20000,25),15000)
        self.assertEqual(net_cents(20000,0),20000)
        self.assertEqual(net_cents(20000,100),0)
        self.assertEqual(net_cents(199,10),179)
    def test_validation(self):
        for a,b in [(-1,10),(100,101),(True,10),(100,False)]:
            with self.assertRaises(ValueError): net_cents(a,b)
